def _daemon_build_sha():
    try:
        with open(os.path.realpath(__file__), "rb") as _f:
            return hashlib.sha256(_f.read()).hexdigest()[:12]
    except Exception:
        return "unknown"
DAEMON_BUILD_SHA = _daemon_build_sha()

