# ─── S06 Share Clones (0.6q) ────────────────────────────────────────────────
# Design canon: MaraDen/share-clones-design-20260924.md (sha f55a9ab9e6922a).
# K80 rulings 2026-09-23: the sharer pays for API + model + tiers ("Period.");
# all boxes OFF by default (pure chat); link + generated password; enable/
# disable switch; separate namespaces. Grants/inbox/presence dead-man land in
# 0.6r; memories/history/merge-back in 0.6s. A share is a synthetic registry
# principal (role=guest) that can NEVER exceed its creator, rides the
# creator's provider keys (no key duplication), and dies clean on delete.
SHARE_MAX_PER_OWNER = 20
_SHARE_LABEL_MAX = 64
SHARE_CHAT_BURST = 20      # messages a guest can fire in a burst...
SHARE_CHAT_PER_MIN = 6     # ...then this sustained rate per share
_SHARE_SID_RE = re.compile(r"^[0-9a-f]{8}$")
_SHARE_PRIN_RE = re.compile(r"^share-([0-9a-f]{8})$")
def _is_share_principal(username):
    return bool(username) and bool(_SHARE_PRIN_RE.match(username or ""))
def share_get(sid):
    with _reg_db() as db:
        return db.execute("SELECT * FROM shares WHERE id=?", (sid,)).fetchone()
def share_get_by_principal(principal):
    with _reg_db() as db:
        return db.execute("SELECT * FROM shares WHERE principal=?", (principal,)).fetchone()
def _owns_share_principal(username, principal):
    # R9/B6: True when `username` is the registered sharer of the share
    # principal `principal` (a conversation's user_id). This is the
    # sharer/owner half of the destructive-ops fence: owners manage their own
    # share's threads through their OWN sessions. Unknown or deleted share
    # principals belong to nobody - fail closed.
    if not username or not _is_share_principal(principal):
        return False
    sh = share_get_by_principal(principal)
    return sh is not None and sh["owner"] == username
def _share_alive(sh):
    if sh is None or not int(sh["enabled"] or 0):
        return False
    _exp = sh["expires_at"]
    return not (_exp and _exp < time.time())
def _share_public_row(sh):
    return {"id": sh["id"], "label": sh["label"], "owner": sh["owner"],
            "enabled": bool(int(sh["enabled"] or 0)), "created_at": sh["created_at"],
            "expires_at": sh["expires_at"], "alive": _share_alive(sh),
            "url": "/share/" + sh["id"]}
def share_create(owner_username, label, expires_days, include_mem=False):
    """Creation ceremony (canon): random principal + random password shown
    ONCE. Persona copied into the share's OWN settings row; the sharer's
    Tier-1 copy is snapshotted ONLY when they keep one (the owner's Tier 1 IS
    the global base - owner shares project it live; documented asymmetry)."""
    label = re.sub(r"[\x00-\x1f\x7f]", "", str(label or "")).strip()[:_SHARE_LABEL_MAX]
    if not label:
        return None, "label required (max " + str(_SHARE_LABEL_MAX) + " chars)", None
    try:
        days = int(expires_days or 0)
    except Exception:
        days = 0
    days = max(0, min(days, 3650))
    with _reg_db() as db:
        n = db.execute("SELECT COUNT(*) FROM shares WHERE owner=?", (owner_username,)).fetchone()[0]
    if n >= SHARE_MAX_PER_OWNER:
        return None, "share limit reached (" + str(SHARE_MAX_PER_OWNER) + " per principal)", None
    pw = os.urandom(12).hex()
    salt = os.urandom(16).hex()
    sid = ""
    for _try in range(8):
        cand = os.urandom(4).hex()
        if share_get(cand) or registry_get_user("share-" + cand):
            continue
        sid = cand
        break
    if not sid:
        return None, "could not mint a share id - try again", None
    principal = "share-" + sid
    registry_create_user(principal, pw, display_name=label, agent_name=label,
                         slug=principal, role="guest", status="active",
                         approved_at=time.time())
    has_t1 = 0
    try:
        _cp = _tier1_file(owner_username)  # personal copy? snapshot it.
        if _cp is not None and _cp.exists():
            _tp = _tier1_target(principal)
            if _tp is not None:
                _tp.parent.mkdir(parents=True, exist_ok=True)
                _tp.write_text(_cp.read_text())
                has_t1 = 1
    except Exception:
        log.warning("S06: tier1 snapshot failed for share by %s - this share projects the global base", owner_username)
    _persona = (get_setting("custom_instructions", "", owner_username) or "")
    expires_at = (time.time() + days * 86400.0) if days else None
    try:
        with _reg_db() as db:
            db.execute(
                "INSERT INTO shares (id, principal, owner, label, salt, pw_hash, enabled, expires_at, created_at, has_tier1)"
                " VALUES (?,?,?,?,?,?,1,?,?,?)",
                (sid, principal, owner_username, label, salt, _hash_pw(pw, salt),
                 expires_at, time.time(), has_t1))
        if _persona:
            set_setting("custom_instructions", _persona, principal)
        # S06 (0.6s): the include-memories box (canon ruling 5) - the ONE
        # deliberate exception to an empty share namespace. One-way copy,
        # capped; originals untouched; projection still gated by allow_memory.
        _mem_n = 0
        if include_mem:
            _mem_n = _share_copy_memories_at_creation(share_get(sid), owner_username)
    except Exception:
        log.exception("S06: share create rollback for %s", owner_username)
        try:
            with _reg_db() as db:
                db.execute("DELETE FROM users WHERE username=?", (principal,))
        except Exception:
            pass
        return None, "share creation failed - nothing was kept", None
    _sp_clear_principal(principal)
    log_event(owner_username, "share.create", share_id=sid, memories_copied=_mem_n)
    _row = _share_public_row(share_get(sid))
    if _mem_n:
        _row["memories_copied"] = _mem_n
    return _row, None, pw
def share_rotate_password(sh):
    pw = os.urandom(12).hex()
    salt = os.urandom(16).hex()
    try:
        with _reg_db() as db:
            db.execute("UPDATE shares SET salt=?, pw_hash=? WHERE id=?", (salt, _hash_pw(pw, salt), sh["id"]))
        # the OLD password's sessions die with it - rotation is revocation
        _su = registry_get_user(sh["principal"])
        if _su:
            sessions_delete_all(sh["principal"])
    except Exception:
        return None, "rotation failed"
    log_event(sh["owner"], "share.rotate", share_id=sh["id"])
    return pw, None
def share_set_enabled(sh, enabled):
    with _reg_db() as db:
        db.execute("UPDATE shares SET enabled=? WHERE id=?", (1 if enabled else 0, sh["id"]))
    if not enabled:
        sessions_delete_all(sh["principal"])  # disable = instant kick
    log_event(sh["owner"], "share.enabled" if enabled else "share.disabled", share_id=sh["id"])
def share_set_expiry(sh, days):
    try:
        days = int(days or 0)
    except Exception:
        return "days must be a number"
    days = max(0, min(days, 3650))
    expires_at = (time.time() + days * 86400.0) if days else None
    with _reg_db() as db:
        db.execute("UPDATE shares SET expires_at=? WHERE id=?", (expires_at, sh["id"]))
    log_event(sh["owner"], "share.expiry", share_id=sh["id"], days=days)
    return None
def share_delete(sh):
    """Delete ceremony, order-fixed (canon): sessions -> conversations +
    messages/compactions/attachments rows -> uploads dirs -> settings rows ->
    memory dir (containment-guarded) -> tier1 copy + pristine -> share row ->
    user row. No orphan escapes; nothing outside the share's namespace is
    ever touched."""
    principal = sh["principal"]
    sessions_delete_all(principal)
    try:
        with sqlite3.connect(DB_PATH) as db:
            cids = [r[0] for r in db.execute("SELECT id FROM conversations WHERE user_id=?", (principal,)).fetchall()]
            for cid in cids:
                db.execute("DELETE FROM messages WHERE conv_id=?", (cid,))
                db.execute("DELETE FROM compactions WHERE conv_id=?", (cid,))
                try:
                    # V15: count the bytes, delete the rows, hand the quota
                    # back - in that order, per conversation.
                    _w_sz = db.execute(
                        "SELECT COALESCE(SUM(size),0) FROM attachments WHERE conv_id=?",
                        (cid,)).fetchone()[0]
                    db.execute("DELETE FROM attachments WHERE conv_id=?", (cid,))
                    _quota_release(db, principal, _w_sz)
                except Exception:
                    pass
                db.execute("DELETE FROM conversations WHERE id=?", (cid,))
            db.execute("DELETE FROM settings WHERE username=?", (principal,))
            db.commit()
        for cid in cids:
            if _valid_conv_id(cid):  # belt: never rmtree a traversal
                shutil.rmtree(UPLOADS_DIR / cid, ignore_errors=True)
    except Exception:
        log.exception("S06: share content delete failed for %s", principal)
    try:
        md = _user_memory_dir(principal)
        # B5: containment via resolve() - the dir must be a DIRECT real child
        # of MEMORY_DIR. A symlinked namespace resolves away and is never
        # removed. Covers seed + room/ + visits/ in one rmtree.
        if md is not None and md.resolve().parent == MEMORY_DIR.resolve() and md.exists():
            shutil.rmtree(md, ignore_errors=True)
    except Exception:
        pass
    try:
        tp = _tier1_target(principal)
        if tp is not None:
            for p in (tp, tp.with_name(tp.name + ".pristine")):
                try:
                    p.unlink()
                except FileNotFoundError:
                    pass
    except Exception:
        pass
    with _reg_db() as db:
        db.execute("DELETE FROM shares WHERE id=?", (sh["id"],))
        db.execute("DELETE FROM users WHERE username=?", (principal,))
    _sp_clear_principal(principal)
    log_event(sh["owner"], "share.delete", share_id=sh["id"])
def _share_path_allowed(p):
    """S06 guest allowlist (deny by default - this IS the security model):
    what a role=guest session may touch. Everything else reads as anonymous:
    APIs 401, pages redirect to login. The guest's own conversations are
    scoped by user_id on every route below, unchanged."""
    if p == "/share" or p.startswith("/share/"):
        return True
    if p in ("/api/me", "/api/logout", "/api/chat", "/api/stop", "/api/conversations", "/health"):
        return True
    if p.startswith("/api/conversations/"):
        return p.endswith("/messages") or p.endswith("/delete")
    if p.startswith("/api/stream/") or p.startswith("/api/attachments/"):
        return True  # both owner-checked downstream
    return False
def _share_gate(h, u):
    """Request-time share fence (revocation is real): expired or disabled
    shares die HERE, mid-life, and their sessions are swept. Guests also get
    the message nozzle. Returns True when the caller must stop."""
    sh = share_get_by_principal(u["username"])
    if sh is None:
        h._json(403, {"error": "this share no longer exists"})
        return True
    if not _share_alive(sh):
        sessions_delete_all(u["username"])
        h._json(403, {"error": "this share is closed"})
        return True
    if not _rate_allow("sharechat|" + u["username"], SHARE_CHAT_BURST, SHARE_CHAT_PER_MIN):
        h._json(429, {"error": "this share has a message limit - try again in a moment"})
        return True
    return False
# ── S06 0.6r: grants, approval inbox, presence dead-man ─────────────────────
# Canon: MaraDen/share-clones-design-20260924.md (0.6r addendum). K80 rulings
# verbatim: every box OFF by default; 1-minute presence dead-man; approvals
# land in the inbox, never inline in the sharer's own chat.
SHARE_PRESENCE_TTL = 60      # K80's "1 minute", dead-man strict
SHARE_APPROVAL_TTL = 86400   # stale pending approvals expire after 24h
SHARE_ASK_MAX_PENDING = 5    # per share - no inbox spam
SHARE_ASK_NAME = "ask_sharer_for_tool"
SHARE_MEMORY_TOOLS = frozenset(("memory", "recall"))
SHARE_ASK_SCHEMA = {"type": "function", "function": {
    "name": SHARE_ASK_NAME,
    "description": ("Ask the person who owns this share clone (the sharer) to "
        "approve one tool for this clone. Creates a request in their approval "
        "inbox - it grants NOTHING by itself and must never be promised to the "
        "guest. Use only when a tool would genuinely help the guest."),
    "parameters": {"type": "object", "properties": {
        "tool_name": {"type": "string", "description": "the exact tool name you would like"},
        "why": {"type": "string", "description": "one short sentence for the sharer"}},
        "required": ["tool_name"]}}}
def _share_grants(sh):
    """Parsed grant columns (all default OFF, K80 ruling 2). Accepts Row or dict."""
    sh = dict(sh)
    try:
        raw = json.loads(sh.get("tools") or "[]")
        names = sorted({n for n in raw if isinstance(n, str)}) if isinstance(raw, list) else []
    except Exception:
        names = []
    return {"allow_tools": int(sh.get("allow_tools") or 0),
            "tools": names,
            "allow_memory": int(sh.get("allow_memory") or 0),
            "allow_history": int(sh.get("allow_history") or 0),
            # B16 (round-9): projection switches, DEFAULT ON (0.6v behavior:
            # Tier-0 + Tier-2 rode every share clone). A missing key (explicit
            # column lists, pre-migration reads) reads as ON = byte preserve.
            "project_tier0": 1 if sh.get("project_tier0") is None else int(sh.get("project_tier0") or 0),
            "project_tier2": 1 if sh.get("project_tier2") is None else int(sh.get("project_tier2") or 0)}
# C04 (K80 law 2026-09-25, audit round 8): the SHARE-SAFE TOOL FLOOR. A share
# clone can only ever carry chat-adjacent tools - the user-tier universe
# (observed: web_search, web_fetch, memory, recall). Host-global capability
# (execute_shell, ssh_run, read/write/edit_file, grep/glob, send_file,
# run_with_secret, every credential connector) is refused BY ABSENCE from the
# floor, no matter who owns the share - not even the owner may mint a clone
# with shell hands. Lazy helper (not a module constant) because
# _sharer_tool_ceiling sits above the TIER_TOOLS definition site in this
# file; name resolution happens at call time.
def _share_safe_set():
    try:
        fs = frozenset(TIER_TOOLS.get("user"))
    except Exception:
        fs = frozenset()
    return fs & frozenset({"web_search", "web_fetch", "memory", "recall"}) \
        if fs else frozenset({"web_search", "web_fetch", "memory", "recall"})


def _sharer_tool_ceiling(owner_username):
    """What the CREATOR can do right now (live). A clone is always share.tools
    intersected with THIS - disabling a tool on yourself shrinks every clone.
    0.6t X (audit round 7, K80-approved): the clone ceiling ALSO passes the
    SEC4 execution fence (allow_tools_for, P1-A/C1). The live tool list alone
    let a brain-only creator (e.g. an admin on an owner-tier box) mint a clone
    with tools they cannot personally use through any other door. If the
    creator cannot run tools at all, the clone ceiling is EMPTY by law."""
    try:
        u = registry_get_user(owner_username)
        if not allow_tools_for(u):
            return frozenset()
        # C04: intersect with the share-safe floor AFTER the live-creator
        # ceiling. Even an owner-tier creator whose own hands include the
        # shell can only offer a clone the chat-adjacent set.
        return frozenset(effective_tool_names(owner_username)) & _share_safe_set()
    except Exception:
        return frozenset()
def _cancel_runs_for(principals):
    """C02 immediate halt (K80 hard requirement): fire the cancel event of
    every in-flight run owned by any principal in the list. Reuses the
    /api/stop registry - same threading.Event, same agent-loop check.
    Best-effort per run: the session kill and the request fence have already
    fired before this is called, so a lookup failure can never leave a NEW
    run alive - it can only fail to hurry an old one."""
    principals = [p for p in (principals or []) if p]
    if not principals:
        return 0
    hits = 0
    try:
        with sqlite3.connect(DB_PATH) as db:
            q = ",".join("?" * len(principals))
            rows = db.execute("SELECT id FROM conversations WHERE user_id IN (" + q + ")",
                              principals).fetchall()
        for r in rows:
            ev = _CANCEL_EVENTS.get(r[0])
            if ev is not None:
                ev.set()
                hits += 1
    except Exception:
        pass
    return hits


def _b19_still_allowed(username, tool_name):
    """B19/H07: LIVE revocation re-check at every side-effecting tool
    dispatch. The turn-start tool set is only a snapshot; this consults
    the registry NOW: status must be active, the role fence must still
    pass for the current row, and the tool must be in the LIVE effective
    set (share enablement, presence, grants, per-user disables all flow
    through effective_tool_names). Fail-closed on any registry error -
    a dead registry must never become a grant. Cost: one small registry
    read per tool call; calls are seconds apart, not per token."""
    if not username or not tool_name:
        return False
    try:
        with _reg_db() as db:
            row = db.execute("SELECT * FROM users WHERE username=?",
                             (username,)).fetchone()
        if row is None or (row["status"] or "") != "active":
            return False
        if not allow_tools_for(row):
            return False
        return tool_name in effective_tool_names(username)
    except Exception:
        return False


def _share_presence_touch(owner_username):
    try:
        with _reg_db() as db:
            db.execute("INSERT INTO share_presence (owner, seen_at) VALUES (?,?)"
                       " ON CONFLICT(owner) DO UPDATE SET seen_at=excluded.seen_at",
                       (owner_username, time.time()))
            db.commit()
    except Exception:
        log.warning("S06r: presence touch failed for %s", owner_username)
def _share_presence_fresh(owner_username):
    try:
        with _reg_db() as db:
            row = db.execute("SELECT seen_at FROM share_presence WHERE owner=?",
                             (owner_username,)).fetchone()
        return bool(row and (time.time() - float(row["seen_at"] or 0)) <= SHARE_PRESENCE_TTL)
    except Exception:
        return False   # dead-man: unreadable presence means the tools are OFF
def _share_memory_allowed(principal):
    sh = share_get_by_principal(principal)
    return bool(sh) and bool(_share_grants(sh)["allow_memory"])
def _share_effective_tools(principal):
    """0.6r: the whole share-tool model in ONE function, behind the same
    choke point as everything else. Grants intersected with the LIVE ceiling,
    gated by the presence dead-man (K80 ruling 7: away >60s = chat-only, no
    tools at all - not even the tool that asks for tools)."""
    sh = share_get_by_principal(principal)
    if sh is None or not _share_alive(sh):
        return frozenset()
    if not _share_presence_fresh(sh["owner"]):
        return frozenset()
    ceiling = _sharer_tool_ceiling(sh["owner"])
    if not ceiling:
        return frozenset()
    names = {SHARE_ASK_NAME}
    g = _share_grants(sh)
    if g["allow_tools"]:
        names |= (set(g["tools"]) & set(ceiling))
    if not g["allow_memory"]:
        names -= SHARE_MEMORY_TOOLS
    return frozenset(names)
# ── S06 0.6s: memory copy-at-creation, projection gate, history box, merge-back ─
# Canon rulings 5 + 8: memories created inside a share stay SEPARATE; merge-back
# is per-file, human-reviewed, provenance-marked ("learned during a share, not
# lived experience"). The copy-at-creation box is the one deliberate exception
# to an empty namespace (K80 checked the box; ruling 5, "document the cliff,
# don't nanny"). Enforcement stays at existing choke points, not new ones.
SHARE_MEM_PREVIEW_CAP = 8000       # review pane caps at ~8KB per file
SHARE_MEM_COPY_CAP  = 262144       # total bytes copied at creation (per share)
SHARE_MEM_PROV = ("Merged back from share '{label}' (share {sid}) on {date}. "
                  "Learned during a share, not lived experience.\n\n")
def _share_mem_dir(principal):
    """Containment: the share's OWN memory directory or None. Re-derives from
    the validated principal string - never from a caller-supplied path."""
    d = _user_memory_dir(principal)
    if d is None or not _is_share_principal(principal):
        return None
    return d
def _share_copy_memories_at_creation(sh, owner_username):
    """The include-memories box: copy the sharer's .md memory files INTO the
    share's namespace (one-way, capped, .md only, silent on any error is NOT
    allowed - returns a count and a note). Never writes outside the share dir."""
    src = _user_memory_dir(owner_username)
    dst = _share_mem_dir(sh["principal"])
    if src is None or dst is None or not src.exists():
        return 0
    copied = total = 0
    try:
        for f in sorted(src.glob("*.md")):
            try:
                data = f.read_bytes()
            except Exception:
                continue
            if total + len(data) > SHARE_MEM_COPY_CAP:
                continue  # per-file skip: one oversized file must not veto the rest
            dst.mkdir(parents=True, exist_ok=True)
            dst.chmod(0o700)
            (dst / f.name).write_bytes(data)
            copied += 1; total += len(data)
        if copied:
            dst.chmod(0o700)
    except Exception:
        log.warning("S06s: copy-at-creation failed for share %s", sh["id"])
    return copied
def _share_mem_list(sh):
    # B5: the review pane lists every layer under its prefix - seed/, room/,
    # visits/<gid>/. Names double as the read/merge keys (layered shapes only;
    # the read path re-validates each one).
    d = _share_mem_dir(sh["principal"])
    out = []
    if d is None or not d.exists():
        return out
    def _add(pdir, lab):
        if not pdir.is_dir():
            return
        for f in sorted(pdir.glob("*.md")):
            try:
                stt = f.stat()
                out.append({"name": lab + f.name, "size": stt.st_size, "mtime": stt.st_mtime})
            except Exception:
                continue
    _add(d, "seed/")
    _add(d / "room", "room/")
    vd = d / "visits"
    if vd.is_dir():
        for p in sorted(vd.iterdir()):
            if p.is_dir() and _R9_GID_RE.match(p.name):
                _add(p, "visits/" + p.name + "/")
    out.sort(key=lambda e: e["name"])
    return out
def _share_mem_read(sh, name):
    """Review pane: read ONE file inside the share namespace, capped. The
    name is validated here, never trusted from the caller otherwise.
    M21 (audit round 8, 0.6u): reads CAP+1 bytes so truncation is DETECTED
    not guessed - the merge path refuses truncated files instead of
    shipping a partial 'success'.
    A8 (round-9): the read opens with O_NOFOLLOW (closes C7's
    exists/resolve/open symlink TOCTOU: no window remains between a check
    and the open) and returns the SHA-256 of the exact bytes read, so a
    merge can be bound to what the owner actually reviewed."""
    d = _share_mem_dir(sh["principal"])
    if d is None or not isinstance(name, str) or ".." in name or not name.endswith(".md"):
        return None, False, None
    if "/" in name:
        # B5: layered review names (seed/x.md, room/x.md, visits/<gid>/x.md).
        # Every segment re-validated by _share_mem_layer_path; the open below
        # stays O_NOFOLLOW, so a swapped-in symlink at ANY level still dies.
        p = _share_mem_layer_path(d, name)
        if p is None:
            return None, False, None
    else:
        p = d / name
    try:
        fd = os.open(str(p), os.O_RDONLY | os.O_NOFOLLOW)
        try:
            buf = b""
            while len(buf) <= SHARE_MEM_PREVIEW_CAP:
                b = os.read(fd, SHARE_MEM_PREVIEW_CAP + 1 - len(buf))
                if not b:
                    break
                buf += b
        finally:
            os.close(fd)
    except Exception:
        return None, False, None
    digest = hashlib.sha256(buf).hexdigest()
    text = buf.decode("utf-8", "replace")
    return text[:SHARE_MEM_PREVIEW_CAP], len(buf) > SHARE_MEM_PREVIEW_CAP, digest
def _share_mem_merge_back(sh, name, decided_by, digest=""):
    """Per-file human-reviewed merge-back into the OWNER's memory namespace,
    provenance-marked, never overwriting (collision gets a numbered suffix).
    Returns (dest_name, None) or (None, error).
    A8 (round-9): the merge is BOUND to the reviewed bytes. The request must
    carry the digest the review read returned; the file is re-read here under
    O_NOFOLLOW and refused unless the digest still matches, so bytes
    overwritten (or swapped) between review and merge can never ship."""
    content, _trunc, cur = _share_mem_read(sh, name)
    if content is None:
        return None, "file not found in the share's memory"
    if _trunc:
        # M21: a truncated preview must never become a "successful" merge.
        return None, ("refusing to merge: file exceeds the %d-character "
                      "review cap (truncated copies are never merged)"
                      % SHARE_MEM_PREVIEW_CAP)
    if not isinstance(digest, str) or len(digest) != 64:
        return None, ("stale review: read the file before merging "
                      "(merge is bound to the reviewed digest)")
    if cur != digest:
        return None, ("refusing to merge: file changed since review - "
                      "read it again (merge is bound to the reviewed digest)")
    dst_dir = _user_memory_dir(sh["owner"])
    if dst_dir is None:
        return None, "owner namespace unavailable"
    # B5: a layered review name must never inject "/" into the owner-namespace
    # dest. Seed/room merge to share-<sid>-<base>.md (old shape); visits carry
    # their gid so two visits of one file keep distinct dests.
    _bn = name.rsplit("/", 1)[-1]
    _tag = ("-" + name.split("/")[1]) if name.startswith("visits/") else ""
    base = "share-" + sh["id"] + _tag + "-" + _bn
    dest = dst_dir / base
    n = 2
    while dest.exists() and n < 100:
        dest = dst_dir / ("share-%s%s-%s-%d.md" % (sh["id"], _tag, _bn[:-3], n)); n += 1
    if dest.exists():
        return None, "too many numbered collisions - clean up memory and retry"
    try:
        _lab = sh["label"]
    except Exception:
        _lab = "untitled"
    prov = SHARE_MEM_PROV.format(label=str(_lab or "untitled"),
                                 sid=sh["id"], date=time.strftime("%Y-%m-%d"))
    try:
        dst_dir.mkdir(parents=True, exist_ok=True)
        dst_dir.chmod(0o700)
        # A8: O_CREAT|O_EXCL 0600 - the destination is created exactly once,
        # never clobbers anything, and closes the exists()/write race on the
        # numbered-collision path.
        fd = os.open(str(dest), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        try:
            os.write(fd, (prov + content).encode("utf-8"))
        finally:
            os.close(fd)
    except Exception as e:
        return None, "write failed: %s" % e
    reload_identity()
    log_event(sh["owner"], "share.memory.merged", share_id=sh["id"], file=dest.name)
    return dest.name, None
def _share_memories_api_get(h):
    u = h._need_user()
    if not u:
        return
    qs = urllib.parse.parse_qs(urllib.parse.urlparse(h.path).query)
    sid = (qs.get("id") or [""])[0]
    sh = share_get(sid) if _SHARE_SID_RE.match(sid) else None
    if sh is None or sh["owner"] != u["username"]:  # C02 self-only
        h._json(404, {"error": "not found"})
        return
    h._json(200, {"files": _share_mem_list(sh), "label": sh["label"]})
def _share_memories_api_post(h):
    u = h._need_user()
    if not u:
        return
    body = h._read_body()
    if body is None:
        return
    try:
        body = json.loads(body)
    except Exception:
        h._json(400, {"error": "invalid JSON body"})
        return
    if not isinstance(body, dict):
        h._json(400, {"error": "JSON body must be an object"})
        return
    sid = str(body.get("id") or "")
    sh = share_get(sid) if _SHARE_SID_RE.match(sid) else None
    if sh is None or sh["owner"] != u["username"]:  # C02 self-only
        h._json(404, {"error": "not found"})
        return
    action = body.get("action")
    name = str(body.get("name") or "")
    if action == "read":
        c, _tr, _dig = _share_mem_read(sh, name)
        if c is None:
            h._json(404, {"error": "not found"})
            return
        h._json(200, {"name": name, "content": c, "truncated": _tr, "digest": _dig})
        return
    if action == "merge":
        dest, err = _share_mem_merge_back(sh, name, u["username"],
                                          str(body.get("digest") or ""))
        if err:
            h._json(400, {"error": err})
            return
        h._json(200, {"ok": True, "merged_as": dest})
        return
    h._json(400, {"error": "unknown action"})
def _share_history_allowed(principal):
    """S06 (0.6s): the guest-side history box (0.6r addendum, enforceable
    now). Fail-closed: anything unparseable means 'not allowed'.
    NOTE (scar): rows from the registry are sqlite3.Row - NO .get() method.
    A .get() inside a fail-closed try/except is a silent always-deny bug."""
    try:
        sh = share_get_by_principal(principal)
        if sh is None:
            return False
        return bool(int(sh["allow_history"] or 0))
    except Exception:
        return False
# ─── B5 (round-9, 0.6w): per-guest memory while private ─────────────────────
# C03 stamped conversations by visit but left the MEMORY plane principal-wide:
# with history OFF, guest A's facts rode into guest B's system prompt. The
# share namespace is layered now: <base> = the seed copy (read-only in every
# mode), room/ = the write layer while history is ON (group room), and
# visits/<gid>/ = one partition per guest visit while history is OFF. The gid
# is the session/conversation stamp - guests never choose or see it.
_R9_GID_RE = re.compile(r"[0-9a-f]{16}\Z")
VISIT_MAX_DIRS = 200            # visit dirs kept per share (pruned at login)
VISIT_MAX_BYTES = 1024 * 1024   # summed bytes per single visit partition
def _share_mem_write_dir(principal, gid):
    """The ONE directory a share clone may write right now - or None (fail
    closed): seed is never writable, and a missing/forged gid in private mode
    writes nothing at all."""
    base = _share_mem_dir(principal)
    if base is None:
        return None
    try:
        if _share_history_allowed(principal):
            return base / "room"     # group-room mode: one shared layer
    except Exception:
        return None                  # unparseable state: nowhere to write
    if not isinstance(gid, str) or not _R9_GID_RE.match(gid):
        return None                  # private mode, no valid visit: refuse
    return base / "visits" / gid
def _share_mem_layer_path(base, name):
    """Layered review name -> contained path, or None. ONLY the three known
    shapes; the visit segment must re-match the gid regex, so traversal and
    forged layers die here regardless of what the caller sent."""
    if not isinstance(name, str) or ".." in name or not name.endswith(".md"):
        return None
    seg = name.split("/")
    if len(seg) == 2 and seg[0] in ("seed", "room") and seg[1]:
        return base / seg[0] / seg[1]
    if len(seg) == 3 and seg[0] == "visits" and seg[1] and seg[2]:
        if not _R9_GID_RE.match(seg[1]):
            return None
        return base / "visits" / seg[1] / seg[2]
    return None
def _share_mem_read_dirs(principal, gid):
    """(dir, label-prefix) pairs projected into the prompt, seed first.
    B5 mode-switch ruling: the room layer is projected whenever it EXISTS.
    Guests already shaped by room facts keep them when history flips OFF -
    the room goes read-only (it stops taking notes the moment visits take
    over) but un-remembering what every guest already saw would be worse
    than keeping it. When history is ON, private visit partitions stay UN-
    projected - flipping a share public never smuggles private visit notes
    into the group prompt. Owners still review/merge them via the review API."""
    base = _share_mem_dir(principal)
    if base is None:
        return []
    out = [(base, "seed/")]
    room = base / "room"
    if room != base and room.is_dir():
        out.append((room, "room/"))
    w = _share_mem_write_dir(principal, gid)
    if w is not None and w != room:
        out.append((w, "visit/"))
    return out
def _conv_guest_id(conv_id, username=None):
    """B5: the executing conversation's OWN guest stamp (STATE db) - exactly
    how recall derives visit scope. Empty/mismatched/no row -> None -> the
    write layer fails closed."""
    if not conv_id:
        return None
    try:
        with sqlite3.connect(DB_PATH) as db:
            if username is not None:
                row = db.execute("SELECT guest_id FROM conversations WHERE id=? AND user_id=?",
                                 (conv_id, username)).fetchone()
            else:
                row = db.execute("SELECT guest_id FROM conversations WHERE id=?",
                                 (conv_id,)).fetchone()
        return row[0] if row else None
    except Exception:
        return None
def _visit_prune(principal):
    """Cap the visits layer: empty dirs always go; beyond VISIT_MAX_DIRS the
    oldest (mtime) partitions are dropped whole. Called on guest login, where
    fresh stamps mint. Never touches seed or room."""
    base = _share_mem_dir(principal)
    if base is None:
        return
    vd = base / "visits"
    if not vd.is_dir():
        return
    try:
        entries = []
        for p in vd.iterdir():
            if not p.is_dir() or not _R9_GID_RE.match(p.name):
                continue   # foreign junk: leave it (rmtree of visits is never in scope)
            try:
                stt = p.stat()
            except Exception:
                continue
            has_files = False
            try:
                has_files = any(f.is_file() for f in p.iterdir())
            except Exception:
                pass
            entries.append((stt.st_mtime, p, has_files))
        gone = 0
        keep = []
        for mtime, p, has_files in sorted(entries, key=lambda t: t[0]):
            if not has_files:
                gone += 1
                try:
                    shutil.rmtree(p, ignore_errors=True)
                except Exception:
                    keep.append((mtime, p))   # could not remove - still counts
            else:
                keep.append((mtime, p))
        n = len(keep)
        for _mtime, p in keep:
            if n <= VISIT_MAX_DIRS:
                break
            gone += 1; n -= 1
            try:
                shutil.rmtree(p, ignore_errors=True)
            except Exception:
                pass
        if gone:
            log.info("B5: pruned %d visit partition(s) for %s", gone, principal)
    except Exception:
        log.warning("B5: visit prune failed for %s", principal)
def _share_approvals_expire():
    try:
        with _reg_db() as db:
            db.execute("UPDATE share_approvals SET status='expired', decided_at=?"
                       " WHERE status='pending' AND created_at < ?",
                       (time.time(), time.time() - SHARE_APPROVAL_TTL))
            db.commit()
    except Exception:
        log.warning("S06r: approval expiry sweep failed")
def _share_ask_execute(username, args):
    """The ask pseudo-tool: a LETTER TO THE INBOX, not a grant."""
    sh = share_get_by_principal(username)
    if sh is None or not _share_alive(sh):
        return "this share is closed"
    if not _rate_allow("shareask|" + sh["id"], 3, 2):
        return "approval requests are rate limited - try again in a bit"
    tool = str((args or {}).get("tool_name") or "").strip()
    why = str((args or {}).get("why") or "")[:280]
    ceiling = _sharer_tool_ceiling(sh["owner"])
    if not ceiling:
        return "the sharer has no tools to share right now"
    if tool not in ceiling:
        return "the sharer cannot use that tool either - nothing to ask for"
    _share_approvals_expire()
    with _reg_db() as db:
        n = db.execute("SELECT COUNT(*) AS c FROM share_approvals"
                       " WHERE share_id=? AND status='pending'", (sh["id"],)).fetchone()["c"]
        if n >= SHARE_ASK_MAX_PENDING:
            return "the inbox already has pending requests for this share - wait for a decision"
        db.execute("INSERT INTO share_approvals (share_id, tool_name, note, status,"
                   " requested_by, created_at) VALUES (?,?,?,?,?,?)",
                   (sh["id"], tool, why, "pending", username, time.time()))
        db.commit()
    log_event(sh["owner"], "share.approval.requested", share_id=sh["id"], tool=tool)
    return ("request sent to the sharer's approval inbox (" + tool + "). It is NOT active -"
            " nothing changes unless the sharer approves. Do not promise the guest anything.")
def _share_set_grants(sh, allow_tools=None, tools=None, allow_memory=None, allow_history=None,
                      project_tier0=None, project_tier2=None):
    """Sharer-side grants edit. Every tool name must sit inside the creator's
    LIVE ceiling - a clone can never exceed its creator (canon invariant).
    Returns an error string or None."""
    cur = _share_grants(sh)
    at = cur["allow_tools"] if allow_tools is None else (1 if allow_tools else 0)
    am = cur["allow_memory"] if allow_memory is None else (1 if allow_memory else 0)
    ah = cur["allow_history"] if allow_history is None else (1 if allow_history else 0)
    p0 = cur["project_tier0"] if project_tier0 is None else (1 if project_tier0 else 0)
    p2 = cur["project_tier2"] if project_tier2 is None else (1 if project_tier2 else 0)
    if tools is None:
        names = cur["tools"]
    else:
        if not isinstance(tools, list) or any(not isinstance(t, str) for t in tools):
            return "tools must be a list of tool names"
        names = sorted(set(tools))
        ceiling = set(_sharer_tool_ceiling(sh["owner"]))
        bad = sorted(t for t in names if t not in ceiling)
        if bad:
            return "you cannot grant a tool you cannot use yourself: " + ", ".join(bad[:6])
    with _reg_db() as db:
        db.execute("UPDATE shares SET allow_tools=?, tools=?, allow_memory=?, allow_history=?,"
                   " project_tier0=?, project_tier2=?"
                   " WHERE id=?", (at, json.dumps(names), am, ah, p0, p2, sh["id"]))
        db.commit()
    # H13 (audit round 8): grants change the projected prompt (tool list +
    # memory section). Cache contract says every projection-affecting write
    # evicts - same one-line pattern as share create/delete.
    _sp_clear_principal(sh["principal"])
    _share_presence_touch(sh["owner"])   # being here IS being present
    return None
def _share_approvals_api_get(h):
    u = h._need_user()
    if not u:
        return
    _share_approvals_expire()
    # C02 (K80 law 2026-09-25): the approval inbox is SELF-ONLY too - staff
    # cannot read other peoples shares' requests. The kill switch is the ONLY
    # staff power over foreign shares.
    with _reg_db() as db:
        rows = db.execute("SELECT a.*, s.label AS share_label FROM share_approvals a"
                          " LEFT JOIN shares s ON s.id = a.share_id"
                          " WHERE s.owner=? ORDER BY a.created_at DESC LIMIT 200",
                          (u["username"],)).fetchall()
    h._json(200, [dict(r) for r in rows])
def _share_approvals_api_post(h):
    # NOTE (scar, REWRITTEN 0.6w V11/R9-C5): the pre-ship flat flow ran
    # the grant edit through _share_set_grants (its own connection, its
    # own commit) BEFORE the decision CAS, so a competing deny could win
    # in between: 400 "already decided" while the grant stayed applied -
    # a lost decision. The decide path now owns ONE connection and ONE
    # BEGIN IMMEDIATE covering the pending check, the grant UPDATE, and
    # the decision CAS; _share_set_grants is deliberately NOT called
    # (its independent commit WAS the bug). The old scar stays true -
    # no nested _reg_db WRITES in this window, and journal mode is NOT
    # WAL, so every write in the txn rides the single connection below.
    u = h._need_user()
    if not u:
        return
    body = h._read_body()
    if body is None:
        return
    try:
        body = json.loads(body)
    except Exception:
        h._json(400, {"error": "invalid JSON body"})
        return
    if not isinstance(body, dict):
        h._json(400, {"error": "JSON body must be an object"})
        return
    action = body.get("action")
    try:
        aid = int(body.get("id"))
    except (TypeError, ValueError):
        h._json(400, {"error": "id must be a number"})
        return
    now = time.time()
    _share_approvals_expire()
    with _reg_db() as db:
        db.execute("BEGIN IMMEDIATE")
        row = db.execute("SELECT a.*, s.owner AS owner_, s.id AS sid,"
                         " s.principal AS principal_, s.enabled, s.expires_at,"
                         " s.tools, s.allow_tools, s.allow_memory, s.allow_history"
                         " FROM share_approvals a"
                         " JOIN shares s ON s.id = a.share_id WHERE a.id=?", (aid,)).fetchone()
        if row is None or row["owner_"] != u["username"]:  # C02 self-only
            db.rollback()
            h._json(404, {"error": "not found"})
            return
        row = dict(row)
        if row["status"] != "pending":
            db.rollback()
            h._json(400, {"error": "this request is already " + str(row["status"])})
            return
        if row["created_at"] < now - SHARE_APPROVAL_TTL:
            db.execute("UPDATE share_approvals SET status='expired', decided_at=? WHERE id=?",
                       (now, aid))
            db.commit()
            h._json(400, {"error": "this request expired - the guest can ask again"})
            return
        decision = None
        if action == "approve":
            # share-alive validation now rides INSIDE the txn (V11 report req)
            if not _share_alive(row):
                db.rollback()
                h._json(400, {"error": "the share is gone or closed"})
                return
            g = _share_grants(row)
            # live-ceiling rule still applies at approve time: a tool the
            # creator lost since the ask cannot be approved back into existence
            ceiling = _sharer_tool_ceiling(row["owner_"])
            if row["tool_name"] not in ceiling:
                db.rollback()
                h._json(400, {"error": "you cannot use that tool right now either - nothing to grant"})
                return
            merged = sorted(set(g["tools"]) | {row["tool_name"]})
            # inline revalidation of the WHOLE merged list (used to live
            # in _share_set_grants): a stale existing tool the creator
            # lost cannot ride back in as a side effect of approving
            bad = sorted(t for t in merged if t not in ceiling)
            if bad:
                db.rollback()
                h._json(400, {"error": "you cannot grant a tool you cannot use yourself: " + ", ".join(bad[:6])})
                return
            db.execute("UPDATE shares SET allow_tools=1, tools=? WHERE id=?",
                       (json.dumps(merged), row["sid"]))
            decision = "approved"
        elif action == "deny":
            decision = "denied"
        else:
            db.rollback()
            h._json(400, {"error": "unknown action"})
            return
        cur = db.execute("UPDATE share_approvals SET status=?, decided_at=?, decided_by=?"
                         " WHERE id=? AND status='pending'",
                         (decision, now, u["username"], aid))
        if cur.rowcount != 1:
            # someone decided first: roll the WHOLE txn back (grant included)
            db.rollback()
            h._json(400, {"error": "this request was already decided"})
            return
        db.commit()
    if decision == "approved":
        # cache evict + presence AFTER commit (V11; H13 cache contract)
        _sp_clear_principal(row["principal_"])
        _share_presence_touch(row["owner_"])
    log_event(row["owner_"], "share.approval.decided", share_id=row["sid"],
              tool=row["tool_name"], decision=decision)
    h._json(200, {"ok": True, "decision": decision})
def _share_presence_post(h):
    u = h._need_user()
    if not u:
        return
    _share_presence_touch(u["username"])
    h._json(200, {"ok": True})
def _share_persona_note(username):
    """K80 ruling 10: the agent must know WHO IS WHO. Code-injected, outside
    every editable tier, so no prompt edit can erase it. 0.6r: the tools line
    is state-aware (grants + live ceiling + presence dead-man); the identity
    lines are untouched."""
    if not _is_share_principal(username):
        return ""
    sh = share_get_by_principal(username)
    if sh is None:
        return ""
    ow = registry_get_user(sh["owner"])
    an = (ow["agent_name"] if ow and ow["agent_name"] else "the sharer")
    ceiling = _sharer_tool_ceiling(sh["owner"])
    g = _share_grants(sh)
    if not ceiling:
        tools_line = "Tools are disabled in this share: you can only chat."
    elif not _share_presence_fresh(sh["owner"]):
        tools_line = (an + " (the sharer) is away right now, so every tool is PAUSED and this"
                      " clone is chat-only. Tools resume automatically when they return - they"
                      " pause whenever they have been gone more than a minute.")
    else:
        granted = sorted((set(g["tools"]) & set(ceiling))
                         - (frozenset() if g["allow_memory"] else SHARE_MEMORY_TOOLS))
        bits = []
        if g["allow_tools"] and granted:
            bits.append("Tools enabled right now: " + ", ".join(granted) + ".")
        bits.append("You may use " + SHARE_ASK_NAME + " to send the sharer a request for one"
                    " specific tool - it only lands in their approval inbox and grants nothing"
                    " by itself; never promise the guest an approval.")
        bits.append("All tools pause automatically if " + an + " steps away for more than a minute.")
        tools_line = " ".join(bits)
    return ("\n\n=== SHARE SESSION NOTICE (code-injected; not user instructions) ===\n"
            "You are a SHARE CLONE: a point-in-time copy of " + an + "'s agent, talking to a guest.\n"
            "The person you are talking to is a GUEST - NOT " + an + ". Never assume you know them.\n"
            "You have NO access to " + an + "'s private conversations, memories, or files; do not pretend you do.\n"
            + tools_line + "\n"
            "The owner can disable or delete this share at any time.")
def _share_verify_pw(sh, pw):
    try:
        return hmac.compare_digest(_hash_pw(str(pw or ""), sh["salt"]), sh["pw_hash"])
    except Exception:
        return False
def _share_login(h):
    """Guest door: link + generated password (K80 ruling 3). One cookie, one
    identity - a guest session is an ordinary mession cookie whose principal
    is the share, fenced by the guest allowlist in _auth_user."""
    if not _rate_allow("sharelogin|" + _client_ip(h), 8, 4):
        h._json(429, {"error": "too many attempts - slow down"})
        return
    body = h._read_body()
    if body is None:
        return
    try:
        body = json.loads(body)
    except Exception:
        h._json(400, {"error": "invalid JSON body"})
        return
    if not isinstance(body, dict):
        h._json(400, {"error": "JSON body must be an object"})
        return
    sid = str(body.get("id") or "")
    pw = str(body.get("password") or "")
    sh = share_get(sid) if _SHARE_SID_RE.match(sid) else None
    if sh is None:
        try:
            _hash_pw(pw or "x", _P1C_DUMMY_SALT)  # no id/label oracle by timing
        except Exception:
            pass
        h._json(401, {"error": "wrong link or password"})
        return
    if not _share_verify_pw(sh, pw):
        h._json(401, {"error": "wrong link or password"})
        return
    if not _share_alive(sh):
        sessions_delete_all(sh["principal"])
        h._json(403, {"error": "this share is closed"})
        return
    u = registry_get_user(sh["principal"])
    if not u or u["status"] != "active":
        h._json(403, {"error": "this share is closed"})
        return
    log_event(sh["principal"], "share.login")
    # C03 (0.6v): per-visit guest identity, minted server-side and riding the
    # session row. Guests never choose it, never see it, cannot forge it.
    tok = session_create(sh["principal"], u["slug"], u["id"], guest_id=os.urandom(8).hex())
    # B5: fresh stamps mint here, so this is the natural moment to cap the
    # visits layer (empty dirs and stale partitions go; seed and room stay).
    try:
        _visit_prune(sh["principal"])
    except Exception:
        pass  # housekeeping - never blocks a login
    h._json(200, {"ok": True}, cookie=_session_cookie(tok, h._cookie_secure()))
def _share_route_get(h, path):
    sid = path[len("/share"):].strip("/").split("/")[0]
    if not _SHARE_SID_RE.match(sid or ""):
        h._html(404, _share_msg_page("Not found", "This share link is not valid."))
        return
    sh = share_get(sid)
    if sh is None:
        h._html(404, _share_msg_page("Not found", "This share link is not valid."))
        return
    u = h._auth_user()
    here = bool(u and u["username"] == sh["principal"])
    if not _share_alive(sh):
        if here:
            sessions_delete_all(sh["principal"])
        h._html(410, _share_msg_page("Closed", "This share is closed. Ask whoever sent you the link for a new one."))
        return
    if here:
        h._html(200, _share_chat_page(sh))
        return
    if u is not None:
        # one cookie, one identity (canon): signed in as somebody else
        h._html(403, _share_msg_page("Wrong identity", "This browser is signed in as a different person. Open this link in a private window, or sign out first.", signout=True))
        return
    h._html(200, _share_pw_page(sh))
def _shares_api_get(h):
    u = h._need_user()
    if not u:
        return
    # C02 (K80 law 2026-09-25): the Shares list is SELF-ONLY. The only staff
    # power over other peoples shares is the kill switch below - not even a read.
    with _reg_db() as db:
        rows = db.execute("SELECT * FROM shares WHERE owner=? ORDER BY created_at DESC", (u["username"],)).fetchall()
    # S19 lesson: raw SELECT * shipped salt+pw_hash to the browser.
    # S06r: rows also carry the grant boxes, the presence state, and the
    # creator's LIVE tool ceiling (names only) so the Shares page can draw
    # honest checkboxes instead of hopeful ones.
    out = []
    for r in rows:
        d = dict(r)
        row = _share_public_row(d)
        row.update(_share_grants(d))
        row["presence_fresh"] = _share_presence_fresh(row["owner"])
        row["sharer_tools"] = sorted(_sharer_tool_ceiling(row["owner"]))
        out.append(row)
    h._json(200, out)
def _shares_api_post(h):
    """Share management API (C02, K80 law 2026-09-25): every active principal
    manages their OWN shares only. Staff (owner/admin, active) get ONE extra
    power: the disable_all kill switch targeting any user. Guests never reach
    here - the allowlist fences /api/shares before auth even resolves them."""
    u = h._need_user()
    if not u:
        return
    body = h._read_body()
    if body is None:
        return
    try:
        body = json.loads(body)
    except Exception:
        h._json(400, {"error": "invalid JSON body"})
        return
    if not isinstance(body, dict):
        h._json(400, {"error": "JSON body must be an object"})
        return
    action = body.get("action")
    if action == "create":
        row, err, pw = share_create(u["username"], body.get("label"), body.get("days"),
                                    include_mem=bool(body.get("include_memories")))
        if err:
            h._json(400, {"error": err})
            return
        h._json(200, {"ok": True, "share": row, "password": pw})  # shown ONCE (canon)
        return
    if action == "disable_all":
        # C02 kill switch (K80 2026-09-25): staff halts EVERY share of one
        # user, immediately. Disable only - never delete, rotate, grants, or
        # reads. Guests are kicked (share_set_enabled kicks sessions), new
        # requests die at _share_gate, and in-flight generations are
        # cancelled NOW via the /api/stop machinery.
        if u["role"] not in ("owner", "admin"):
            h._json(403, {"error": "staff only"})
            return
        tgt = re.sub(r"[^a-zA-Z0-9_-]", "", str(body.get("username") or ""))[:48]
        tu = registry_get_user(tgt) if tgt else None
        if not tu or (tu["role"] or "") == "guest":
            h._json(404, {"error": "user not found"})
            return
        with _reg_db() as db:
            rows = db.execute("SELECT * FROM shares WHERE owner=?", (tu["username"],)).fetchall()
        n = 0
        principals = []
        for r in rows:
            shx = dict(r)
            principals.append(shx["principal"])
            if shx["enabled"]:
                share_set_enabled(shx, False)
                n += 1
        cancelled = _cancel_runs_for(principals)
        log_event(u["username"], "share.killswitch", target=tu["username"],
                  disabled=n, cancelled=cancelled)
        h._json(200, {"ok": True, "disabled": n, "cancelled_runs": cancelled})
        return
    sid = str(body.get("id") or "")
    sh = share_get(sid) if _SHARE_SID_RE.match(sid) else None
    if sh is None or sh["owner"] != u["username"]:
        # C02 (K80 law): enable, disable, rotate, expiry, grants, delete - all
        # SELF-ONLY. Re-enable in particular: only the sharer can lift a
        # disable, not even the staff member who pulled the switch. 404 for
        # non-owners: no enumeration.
        h._json(404, {"error": "not found"})
        return
    if action == "enable":
        share_set_enabled(sh, True)
        h._json(200, {"ok": True})
    elif action == "disable":
        share_set_enabled(sh, False)
        h._json(200, {"ok": True})
    elif action == "rotate":
        pw, err = share_rotate_password(sh)
        if err:
            h._json(500, {"error": err})
            return
        h._json(200, {"ok": True, "password": pw})  # shown ONCE
    elif action == "expiry":
        err = share_set_expiry(sh, body.get("days"))
        if err:
            h._json(400, {"error": err})
            return
        h._json(200, {"ok": True, "share": _share_public_row(share_get(sh["id"]))})
    elif action == "grants":
        # S06r: the three boxes + the tool list. _share_set_grants enforces
        # the canon invariant (a clone never holds a tool its creator
        # cannot use right now). Body keys that are absent are left as-is.
        def _g(k):
            return None if k not in body else bool(body.get(k))
        err = _share_set_grants(sh, allow_tools=_g("allow_tools"),
                                tools=body.get("tools"),
                                allow_memory=_g("allow_memory"),
                                allow_history=_g("allow_history"),
                                project_tier0=_g("project_tier0"),
                                project_tier2=_g("project_tier2"))
        if err:
            h._json(400, {"error": err})
            return
        log_event(u["username"], "share.grants", share_id=sh["id"])
        h._json(200, {"ok": True, "share": _share_public_row(share_get(sh["id"]))})
    elif action == "delete":
        share_delete(sh)
        h._json(200, {"ok": True})
    else:
        h._json(400, {"error": "unknown action"})
# ─── S06 guest + management pages (0.6q) ────────────────────────────────────
# Anonymous share pages carry NO version/build stamp (R5 H7 posture) and no
# markdown rendering (cosmetic polish is later, per canon).
_SHARE_CSS = ("*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,sans-serif;"
              "background:#0b0f16;color:#d8e2ee}main{max-width:720px;margin:0 auto;padding:16px}"
              "h1{font-size:19px}input,textarea{background:#121a26;color:#d8e2ee;border:1px solid #2a3646;"
              "border-radius:8px;padding:10px;font:inherit;width:100%}button{background:#2c624f;color:#eaf6ef;"
              "border:0;border-radius:8px;padding:10px 14px;font:inherit;cursor:pointer}"
              "button.warn{background:#5d2a2a;color:#ffd9d9}.hint{color:#7f8ea3;font-size:12px}"
              ".card{background:#121a26;border:1px solid #2a3646;border-radius:12px;padding:16px;margin:12px 0}")
def _share_shell(title, body):
    return ("<!DOCTYPE html><html lang='en'><head><meta charset='utf-8'>"
            "<meta name='viewport' content='width=device-width, initial-scale=1'>"
            "<title>" + html_mod.escape(title) + "</title><style>" + _SHARE_CSS +
            "</style></head><body><main>" + body + "</main></body></html>")
def _share_msg_page(title, msg, signout=False):
    extra = ("<script>async function so(){await fetch('/api/logout',{method:'POST',credentials:'same-origin'});location.reload()}</script>"
             "<p><button onclick='so()'>Sign out of this account</button></p>") if signout else ""
    return _share_shell(title, "<h1>" + html_mod.escape(title) + "</h1><p>" + html_mod.escape(msg) + "</p>" + extra)
def _share_pw_page(sh):
    body = ("<h1>Shared agent</h1>"
            "<div class='card'><p>You have been invited to chat with a private copy of someone's C.A.I.R.N. agent. "
            "Enter the password they sent you.</p>"
            "<input id='pw' type='password' placeholder='share password' autocomplete='current-password'>"
            "<p><button id='go'>Enter</button> <span id='err' class='hint'></span></p></div>"
            "<p class='hint'>This is a share: the agent here starts as chat-only and cannot reach the sharer's "
            "live chats, files, or memory - it works from copies of whatever the sharer chose to "
            "include (persona, working directions, and memory only if the share enables it). Assume "
            "anything included can be recited back to guests. Any tools are the sharer's choice and "
            "pause while the sharer is away. The sharer can close this share at any time.</p>"
            "<script>const SID='__SID__';const b=document.getElementById('go'),e=document.getElementById('err'),"
            "p=document.getElementById('pw');"
            "async function go(){b.disabled=true;e.textContent='...';try{const r=await fetch('/api/share/login',"
            "{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',"
            "body:JSON.stringify({id:SID,password:p.value})});"
            "if(r.ok){location.reload();return}const d=await r.json().catch(function(){return{}});"
            "e.textContent=d.error||('failed: '+r.status);}catch(x){e.textContent='network error'}b.disabled=false}"
            "b.addEventListener('click',go);p.addEventListener('keydown',function(k){if(k.key==='Enter')go()});"
            "p.focus();</script>")
    return _share_shell("Shared agent", body.replace("__SID__", sh["id"]))
def _share_chat_page(sh):
    ow = registry_get_user(sh["owner"])
    an = (ow["agent_name"] if ow and ow["agent_name"] else "the sharer")
    hdr = html_mod.escape(sh["label"]) + " <span class='hint'>shared by " + html_mod.escape(an) + "</span>"
    body = ("<header><b>" + hdr + "</b><button id='out'>Sign out</button></header>"
            "<div id='log'></div><div id='stat' class='hint'></div>"
            "<div class='row'><textarea id='in' rows='2' placeholder='Type a message'></textarea>"
            "<button id='send'>Send</button></div>"
            "<p class='hint'>Shared chat - no tools. Memories from this chat stay in the share. "
            "The sharer can close it at any time.</p>"
            "<script>const SID='__SID__';const KEY='share-conv-'+SID;"
            "let conv=localStorage.getItem(KEY)||'';if(!conv){conv=(window.crypto&&crypto.randomUUID)?crypto.randomUUID():"
            "('c'+Date.now().toString(36)+Math.random().toString(36).slice(2));localStorage.setItem(KEY,conv)}"
            "const log=document.getElementById('log'),tin=document.getElementById('in'),"
            "sb=document.getElementById('send'),st=document.getElementById('stat');"
            "function div(c,t){const d=document.createElement('div');d.className=c;d.textContent=t;log.appendChild(d);return d}"
            "function esc(s){return String(s).replace(/&/g,String.fromCharCode(38)+'amp;').replace(/</g,String.fromCharCode(60)+'lt;').replace(/>/g,String.fromCharCode(62)+'gt;')}"
            "async function load(){if(!conv)return;try{const r=await fetch('/api/conversations/'+conv+'/messages',{credentials:'same-origin'});"
            "if(!r.ok)return;const ms=await r.json();for(const m of ms){if(m.role==='user')div('me',m.content);"
            "else if(m.content)div('ag',m.content)}}catch(e){}}"
            "async function send(){const t=tin.value.trim();if(!t||sb.disabled)return;tin.value='';sb.disabled=true;"
            "st.textContent='...';div('me',t);let as=null;"
            "try{const r=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},"
            "credentials:'same-origin',body:JSON.stringify({conversation_id:conv,message:t})});"
            "if(!r.ok){const d=await r.json().catch(function(){return{}});div('ag','[Error: '+(d.error||r.status)+']')}else{"
            "const rd=r.body.getReader(),dec=new TextDecoder();let buf='';st.textContent='thinking...';"
            "while(true){const it=await rd.read();if(it.done)break;buf+=dec.decode(it.value,{stream:true});"
            "const parts=buf.split(String.fromCharCode(10)+String.fromCharCode(10));buf=parts.pop();"
            "for(const p of parts){let ev='',data='';for(const ln of p.split(String.fromCharCode(10))){if(ln.indexOf('event: ')===0)ev=ln.slice(7);"
            "else if(ln.indexOf('data: ')===0)data+=(data?String.fromCharCode(10):'')+ln.slice(6)}if(!data)continue;"
            "let d=null;try{d=JSON.parse(data)}catch(e){continue}"
            "if((ev==='conversation'||ev==='done')&&typeof d.conversation_id==='string'&&d.conversation_id){conv=d.conversation_id;localStorage.setItem(KEY,conv)}"
            "if(ev==='message'&&d.content){if(!as)as=div('ag','');as.textContent+=d.content}"
            "else if(ev==='error'){div('ag','[Error: '+(d.message||'unknown')+']');as=null}"
            "else if(ev==='stopped'){div('ag','[stopped]');as=null}"
            "else if(ev==='status'&&d.phase){st.textContent=d.phase}else if(ev==='done'){st.textContent=''}}}}}"
            "catch(e){div('ag','[network error]')}st.textContent='';sb.disabled=false;tin.focus()}"
            "sb.addEventListener('click',send);"
            "tin.addEventListener('keydown',function(k){if(k.key==='Enter'&&!k.shiftKey){k.preventDefault();send()}});"
            "document.getElementById('out').addEventListener('click',async function(){await fetch('/api/logout',"
            "{method:'POST',credentials:'same-origin'});location.href='/share/'+SID});load();</script>")
    return _share_shell("Shared chat", body.replace("__SID__", sh["id"]))
