MANIFEST_WEB = """{"id": "/mara/", "name": "Mara", "short_name": "Mara", "description": "Mara's home on the rock - chat, memory, and the whole house's tools.", "start_url": "/mara/", "scope": "/mara/", "display": "standalone", "orientation": "portrait", "background_color": "#05070d", "theme_color": "#05070d", "icons": [{"src": "/mara/static/color.png", "sizes": "192x192", "type": "image/png", "purpose": "any"}, {"src": "/mara/static/color.png", "sizes": "192x192", "type": "image/png", "purpose": "maskable"}]}"""

SERVICE_WORKER = """/* Mara PWA service worker — app-shell cache, API never cached.
   Mara | Auth: K80 | 2026-09-15 (P3.1) */
const CACHE = 'mara-shell-v1';
const SHELL = ['./', 'settings', 'static/color.png', 'manifest.webmanifest'];

self.addEventListener('install', (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys()
      .then((ks) => Promise.all(ks.filter((k) => k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', (e) => {
  if (e.request.method !== 'GET') return;
  const url = new URL(e.request.url);
  if (url.origin !== self.location.origin) return;
  const p = url.pathname;
  if (p.indexOf('/api/') !== -1 || p.indexOf('/v1/') !== -1 || p.indexOf('/health') !== -1) return;
  e.respondWith(
    fetch(e.request).then((resp) => {
      const copy = resp.clone();
      caches.open(CACHE).then((c) => c.put(e.request, copy));
      return resp;
    }).catch(() =>
      caches.match(e.request).then((r) => r || caches.match('./'))
    )
  );
});"""

# H16 (audit 2026-09-24, K80 "no half-backed fixes"): stock
# ThreadingHTTPServer is thread-per-connection with NO admission control -
# any client that can reach the port can park as many workers as it likes,
# each held for the full socket timeout. The semaphore below is the budget
# the server never had: over budget gets an immediate 503 + close, never a
# queued thread. Env MARA_MAX_WORKERS (default 64) is the whole knob; the
# reverse-proxy guidance in /help/tls still applies (limits there help too).
import threading as _h16_th
MAX_WORKERS = max(4, int(os.environ.get("MARA_MAX_WORKERS", "64") or 64))
_TLS_HANDSHAKE_TIMEOUT = 15.0  # T-A3: bound on one server-side TLS handshake
HEADER_TIMEOUT_S = 15.0  # R9/B9/V12: request line + headers must arrive inside
                         # this. The long P1-B/H16 guard starts only once a
                         # full request exists (MaraHandler.parse_request),
                         # and the header deadline re-arms for EVERY request
                         # on a keep-alive connection (handle_one_request).
PER_IP_MAX = max(4, MAX_WORKERS // 4)  # R9/B9: per-address live-socket cap.
                         # Enforced only when CAIRN faces clients directly
                         # (TLS mode != proxy): behind a reverse proxy every
                         # client shares the proxy's address and the proxy
                         # owns slowloris defence - /help/tls guidance stands.
_ip_live = {}            # R9/B9: accepted sockets currently held, per peer IP
_ip_lock = _h16_th.Lock()
def _ip_admit(ip):
    with _ip_lock:
        n = _ip_live.get(ip, 0)
        if n >= PER_IP_MAX:
            return False
        _ip_live[ip] = n + 1
        return True
def _ip_release(ip):
    with _ip_lock:
        n = _ip_live.get(ip, 1) - 1
        if n <= 0:
            _ip_live.pop(ip, None)
        else:
            _ip_live[ip] = n

class _BoundedHTTPServer(ThreadingHTTPServer):
    daemon_threads = True  # the historical main() posture now lives with the class
    _tls_ctx = None  # T-A3: set by _tls_wire; None => plaintext server
    def __init__(self, *a, **kw):
        super().__init__(*a, **kw)
        self._worker_sem = _h16_th.BoundedSemaphore(MAX_WORKERS)
    def _refuse(self, request):
        # R9/B9: admission refusal (extracted from process_request, same bytes).
        # T-A3: on a TLS server the peer is still waiting for a ServerHello;
        # raw HTTP bytes would be garbage, so the honest 503 is plaintext-only.
        if self._tls_ctx is None:
            try:
                request.sendall(b"HTTP/1.1 503 Service Unavailable\r\n"
                                b"Connection: close\r\nContent-Length: 0\r\n\r\n")
            except OSError:
                pass
        self.shutdown_request(request)
    def process_request(self, request, client_address):
        if not self._worker_sem.acquire(blocking=False):
            return self._refuse(request)
        # R9/B9: per-IP cap AFTER the global slot; an IP refusal hands its
        # global slot straight back. Skipped in proxy mode, where every
        # client shares the proxy's address and the proxy owns slowloris
        # defence (/help/tls guidance unchanged).
        if _TLS_RUNTIME != "proxy" and not _ip_admit(client_address[0]):
            self._worker_sem.release()
            return self._refuse(request)
        _h16_th.Thread(target=self._worker, args=(request, client_address),
                       daemon=True).start()
    def _worker(self, request, client_address):
        try:
            if self._tls_ctx is not None:
                # T-A3: the TLS handshake happens HERE - per accepted
                # connection, inside a bounded worker - never inside accept().
                # The listener stays a plain socket, so an idle or stalled TCP
                # connection can burn at most ONE worker slot (H16 semaphore)
                # and only until the handshake timeout below fires.
                request = self._tls_ctx.wrap_socket(
                    request, server_side=True, do_handshake_on_connect=False)
                request.settimeout(_TLS_HANDSHAKE_TIMEOUT)
                request.do_handshake()
            self.finish_request(request, client_address)
        except Exception:
            self.handle_error(request, client_address)
        finally:
            self.shutdown_request(request)
            if _TLS_RUNTIME != "proxy":  # R9/B9: mirror of the admission
                _ip_release(client_address[0])  # gate; _TLS_RUNTIME is fixed
                                                # for the life of the process
            self._worker_sem.release()
